package selfupdate

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"
	"time"
)

// sumsAsset is the checksum manifest generated by release.yml, covering every zip in the Release.
const sumsAsset = "SHA256SUMS"

// maxBinarySize limits the size of the extracted binary, to prevent a malformed zip from filling the disk.
const maxBinarySize = 512 << 20 // 512 MiB

// Phase is a stage of the upgrade process, used directly as the phase field in SSE events.
type Phase string

const (
	PhaseIdle     Phase = "idle"
	PhaseDownload Phase = "downloading"
	PhaseVerify   Phase = "verifying"
	PhaseExtract  Phase = "extracting"
	PhaseStaged   Phase = "staged"
	PhaseFailed   Phase = "failed"
)

// Progress is provided by the caller to push progress to the frontend. pct is meaningful only during the download phase (0-100);
// other phases pass -1.
type Progress func(ph Phase, pct int, msg string)

// Stage downloads the release package of the given Release for the current platform, verifies it, and stages the new binary as uroboros.new.
//
// It goes through the full zip rather than the bare binary for two reasons: the existing Releases' SHA256SUMS already
// only cover the zips, so going through the zip needs no CI change and is compatible with historical versions already
// published; the zip also carries skills/, leaving a hook for syncing built-in skills in the future. The cost is only
// downloading the extra few hundred KB of skills.
//
// A return from the function means staging is complete, after which the caller shuts down gracefully and exits with ExitRestart.
func Stage(ctx context.Context, c *http.Client, rel *Release, currentVersion string, prog Progress) error {
	return (releaseStage{source: releaseSource{ctx, c}, release: rel, previous: currentVersion, progress: prog}).run()
}

// fetchSums downloads and parses SHA256SUMS, returning filename → hex digest.
func fetchSums(ctx context.Context, c *http.Client, rel *Release) (map[string]string, error) {
	return (releaseSource{ctx, c}).sums(rel)
}

// parseSums parses a sha256sum-style manifest, returning filename → hex digest.
//
// The first field must be 64-digit hex to be included. Judging only by "exactly two fields" is not enough —
// any line of two words of explanatory text would be treated as a valid entry, stuffing a garbage value into the digest table,
// and the real asset might then match the wrong digest.
func parseSums(raw string) map[string]string {
	out := map[string]string{}
	for line := range strings.Lines(raw) {
		// The format is "<sha256>  <filename>" (sha256sum uses two spaces; shasum's binary
		// mode prefixes the filename with *).
		fields := strings.Fields(strings.TrimSpace(line))
		if len(fields) != 2 || !isHexSHA256(fields[0]) {
			continue
		}
		name := strings.TrimPrefix(fields[1], "*")
		if name == "" {
			continue
		}
		out[name] = strings.ToLower(fields[0])
	}
	return out
}

func isHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
		default:
			return false
		}
	}
	return true
}

// download writes the asset to dst while computing the SHA256 and reporting progress by Content-Length.
func download(ctx context.Context, c *http.Client, a Asset, dst string, prog Progress) (string, error) {
	return (releaseSource{ctx, c}).download(a, dst, prog)
}

// get issues an allowlist-constrained GET and returns the response body.
func get(ctx context.Context, c *http.Client, rawURL string) (io.ReadCloser, error) {
	return (releaseSource{ctx, c}).body(rawURL)
}

// extractBinary takes the uroboros executable out of the release package.
//
// The in-package structure is uroboros-<version>-<os>-<arch>/uroboros, but here it matches by **base name** rather than assembling the full
// path: the version appears once in the package name, and one mistyped character would fail the whole upgrade, so matching by base name is more robust.
func extractBinary(zipPath, dst string) error {
	return extractUpdateArtifact(zipPath, dst)
}

// checkWritable confirms up front that the directory is writable. Without this step, running as non-root or placing the binary in a system
// directory would fail only at the moment of the swap, after tens of MB have already been downloaded.
func checkWritable(dir string) error {
	probe, err := os.CreateTemp(dir, ".uroboros-update-probe-*")
	if err != nil {
		return fmt.Errorf("the program directory %s is not writable, cannot auto-update (check permissions or use a manual upgrade): %w", dir, err)
	}
	name := probe.Name()
	_ = probe.Close()
	_ = os.Remove(name)
	return nil
}

// progressWriter counts bytes written and reports at a limited rate, to avoid pushing one SSE per 32KiB chunk.
type progressWriter struct {
	total   int64
	written int64
	name    string
	prog    Progress
	last    time.Time
}

func (w *progressWriter) Write(b []byte) (int, error) {
	w.written += int64(len(b))
	if time.Since(w.last) < 300*time.Millisecond {
		return len(b), nil
	}
	w.last = time.Now()
	pct := -1
	if w.total > 0 {
		pct = int(w.written * 100 / w.total)
	}
	w.prog(PhaseDownload, pct, fmt.Sprintf("downloading %s / %s", humanSize(w.written), humanSize(w.total)))
	return len(b), nil
}

func humanSize(n int64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}
	div, exp := int64(unit), 0
	for v := n / unit; v >= unit; v /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %cB", float64(n)/float64(div), "KMGT"[exp])
}

func short(sum string) string {
	if len(sum) > 12 {
		return sum[:12] + "…"
	}
	return sum
}
